function renderFeed(container, posts, options = {}) {
  const doc = options.document || (typeof document !== 'undefined' ? document : null);
  if (!doc) throw new Error('document is required');
  const role = options.role || container.getAttribute('data-role') || 'member';
  const promptFn = options.prompt || (typeof window !== 'undefined' && window.prompt ? window.prompt.bind(window) : () => null);
  const blockedTags = [];
  container.setAttribute('data-role', role);
  container.innerHTML = '';
  for (const post of posts) {
    const card = doc.createElement('article');
    card.className = 'post-card';
    card.setAttribute('data-post-id', post.id);
    const body = doc.createElement('p');
    body.textContent = post.title;
    card.appendChild(body);
    const tags = doc.createElement('div');
    tags.className = 'tag-list';
    for (const tag of post.tags) {
      const chip = doc.createElement('span');
      chip.className = 'tag-chip';
      chip.setAttribute('data-tag', tag);
      const label = doc.createElement('span');
      label.textContent = tag;
      chip.appendChild(label);
      if (role === 'moderator') {
        const btn = doc.createElement('button');
        btn.type = 'button';
        btn.className = 'mod-tag-block';
        btn.setAttribute('data-mod-control', 'block-tag');
        btn.setAttribute('aria-label', `Block tag ${tag}`);
        btn.textContent = 'x';
        btn.addEventListener('click', () => {
          const raw = promptFn('Reason for Block?');
          const reason = typeof raw === 'string' ? raw.trim() : '';
          if (!reason) return;
          chip.setAttribute('data-blocked', 'true');
          chip.setAttribute('data-block-reason', reason);
          blockedTags.push({ postId: post.id, tag, reason });
        });
        chip.appendChild(btn);
      }
      tags.appendChild(chip);
    }
    card.appendChild(tags);
    container.appendChild(card);
  }
  return { blockedTags };
}

if (typeof module !== 'undefined') module.exports = { renderFeed };
